cases.bad:
return () => {
  panel.style.transform = 'translateX(100%)';
  setTimeout(() => { restoreDomAndStyles(); }, 410);
  // timer fires even if a new session already started
};

cases.good:
return () => {
  let restoreDone = false;
  const restoreNow = () => { if (restoreDone) return; restoreDone = true; restoreDomAndStyles(); };
  pendingRestoreRef.current = restoreNow;      // visible to next run
  setTimeout(() => { pendingRestoreRef.current = null; restoreNow(); }, 410);
};
// next effect run, FIRST statement:
const pending = pendingRestoreRef.current;
if (pending) { pendingRestoreRef.current = null; pending(); }

